import { backdrop } from "@/lib/beton/shared";
import { tv, type VariantProps } from "@/lib/beton/tv";

export const sheet = tv({
  slots: {
    backdrop,
    popup: "fixed z-50 flex flex-col border-border bg-raised text-foreground outline-none",
    header: "flex flex-col gap-2 border-b-3 border-border p-6 pr-16",
    title: "font-display text-2xl font-black leading-tight tracking-tight",
    description: "text-base",
    body: "flex flex-1 flex-col gap-4 overflow-y-auto p-6",
    footer: "flex flex-wrap items-center justify-end gap-3 border-t-3 border-border bg-surface p-6",
    close: "absolute top-4 right-4",
  },
  variants: {
    side: {
      right: { popup: "inset-y-0 right-0 h-dvh w-full border-l-5" },
      left: { popup: "inset-y-0 left-0 h-dvh w-full border-r-5" },
      top: { popup: "inset-x-0 top-0 max-h-[85dvh] border-b-5" },
      bottom: { popup: "inset-x-0 bottom-0 max-h-[85dvh] border-t-5" },
    },
    size: {
      sm: {},
      md: {},
      lg: {},
    },
    variant: {
      primary: { header: "bg-primary" },
      secondary: { header: "bg-secondary" },
      ghost: { header: "bg-raised" },
      danger: { header: "bg-danger" },
    },
  },
  compoundVariants: [
    { side: ["left", "right"], size: "sm", class: { popup: "max-w-xs" } },
    { side: ["left", "right"], size: "md", class: { popup: "max-w-md" } },
    { side: ["left", "right"], size: "lg", class: { popup: "max-w-2xl" } },
  ],
  defaultVariants: {
    side: "right",
    size: "md",
    variant: "ghost",
  },
});

export type SheetVariants = VariantProps<typeof sheet>;

"use client";

import { Dialog as BaseDialog } from "@base-ui/react/dialog";
import { button, type ButtonVariants } from "@/lib/beton/recipes/button.recipe";
import { sheet, type SheetVariants } from "@/lib/beton/recipes/sheet.recipe";
import { createContext, useContext, type ComponentProps, type ReactNode } from "react";
import { CloseIcon } from "@/lib/beton/icons";

const SheetContext = createContext<SheetVariants>({ side: "right", size: "md", variant: "ghost" });

function useStyles() {
  return sheet(useContext(SheetContext));
}

export interface SheetProps extends BaseDialog.Root.Props, SheetVariants {}

function SheetRoot({ side = "right", size = "md", variant = "ghost", ...props }: SheetProps) {
  return (
    <SheetContext.Provider value={{ side, size, variant }}>
      <BaseDialog.Root {...props} />
    </SheetContext.Provider>
  );
}

export interface SheetTriggerProps
  extends Omit<BaseDialog.Trigger.Props, "className">, Pick<ButtonVariants, "variant" | "size"> {
  className?: string;
}

function SheetTrigger({
  variant = "secondary",
  size = "md",
  className,
  ...props
}: SheetTriggerProps) {
  return <BaseDialog.Trigger {...props} className={button({ variant, size, class: className })} />;
}

export interface SheetContentProps extends Omit<BaseDialog.Popup.Props, "className"> {
  className?: string;
  showClose?: boolean;
  closeLabel?: string;
}

function SheetContent({
  className,
  children,
  showClose = true,
  closeLabel = "Close panel",
  ...props
}: SheetContentProps) {
  const styles = useStyles();
  return (
    <BaseDialog.Portal>
      <BaseDialog.Backdrop className={styles.backdrop()} />
      <BaseDialog.Popup {...props} className={styles.popup({ class: className })}>
        {children}
        {showClose ? (
          <BaseDialog.Close
            aria-label={closeLabel}
            className={button({
              variant: "ghost",
              size: "sm",
              iconOnly: true,
              class: styles.close(),
            })}
          >
            <CloseIcon width={18} height={18} />
          </BaseDialog.Close>
        ) : null}
      </BaseDialog.Popup>
    </BaseDialog.Portal>
  );
}

function SheetHeader({ className, ...props }: ComponentProps<"div">) {
  return <div {...props} className={useStyles().header({ class: className })} />;
}

function SheetTitle({
  className,
  ...props
}: Omit<BaseDialog.Title.Props, "className"> & { className?: string }) {
  return <BaseDialog.Title {...props} className={useStyles().title({ class: className })} />;
}

function SheetDescription({
  className,
  ...props
}: Omit<BaseDialog.Description.Props, "className"> & { className?: string }) {
  return (
    <BaseDialog.Description {...props} className={useStyles().description({ class: className })} />
  );
}

function SheetBody({ className, ...props }: ComponentProps<"div">) {
  return <div {...props} className={useStyles().body({ class: className })} />;
}

function SheetFooter({ className, ...props }: ComponentProps<"div">) {
  return <div {...props} className={useStyles().footer({ class: className })} />;
}

export interface SheetCloseProps
  extends Omit<BaseDialog.Close.Props, "className">, Pick<ButtonVariants, "variant" | "size"> {
  className?: string;
  children?: ReactNode;
}

function SheetClose({ variant = "secondary", size = "md", className, ...props }: SheetCloseProps) {
  return <BaseDialog.Close {...props} className={button({ variant, size, class: className })} />;
}

/**
 * A panel anchored to an edge of the screen. Behaves like a dialog: focus is
 * trapped, Escape and an outside click close it, and focus returns to the trigger.
 */
export const Sheet = Object.assign(SheetRoot, {
  Trigger: SheetTrigger,
  Content: SheetContent,
  Header: SheetHeader,
  Title: SheetTitle,
  Description: SheetDescription,
  Body: SheetBody,
  Footer: SheetFooter,
  Close: SheetClose,
});
